      };
    in
    pkgs.claude-code.overrideAttrs (_: {
      version = claudeVersion;
      src = pkgs.fetchurl {
        url = "https://downloads.claude.ai/claude-code-releases/${claudeVersion}/${platformKey}/claude";
        sha256 = checksums.${platformKey};
      };
    });

